# ==============================================================================# 099_BILLING_ENGINE.py## IOTEC BILLING ENGINE## Missão:# Gerar cobranças comerciais a partir de contratos.# ==============================================================================from __future__ import annotationsimport sqlite3import uuidimport hashlibimport jsonfrom pathlib import Pathfrom datetime import datetime, timedeltaDB = Path("iotec.db")class BillingEngine:    def __init__(self):        self.conn = sqlite3.connect(DB)        self.conn.row_factory = sqlite3.Row        self.conn.execute("""        CREATE TABLE IF NOT EXISTS commercial_billings(            id INTEGER PRIMARY KEY AUTOINCREMENT,            billing_uuid TEXT UNIQUE,            contract_uuid TEXT,            invoice_number TEXT,            amount REAL,            currency TEXT,            issue_date TEXT,            due_date TEXT,            paid_at TEXT,            payment_method TEXT,            status TEXT,            created_at TEXT,            metadata TEXT,            hash TEXT        )        """)        self.conn.commit()    # ------------------------------------------------------------------    def _sha(self,obj):        raw=json.dumps(            obj,            ensure_ascii=False,            sort_keys=True        )        return hashlib.sha256(raw.encode()).hexdigest()    # ------------------------------------------------------------------    def create_billing(self, contract_uuid):        contrato=self.conn.execute("""            SELECT *            FROM commercial_contracts            WHERE contract_uuid=?            LIMIT 1        """,(contract_uuid,)).fetchone()        if contrato is None:            raise RuntimeError("Contrato não encontrado.")        numero="FAT-"+datetime.utcnow().strftime("%Y%m%d%H%M%S")        emissao=datetime.utcnow()        vencimento=emissao+timedelta(days=30)        payload={            "billing_uuid":str(uuid.uuid4()),            "contract_uuid":contrato["contract_uuid"],            "invoice_number":numero,            "amount":contrato["contract_value"],            "currency":"BRL",            "issue_date":emissao.isoformat(),            "due_date":vencimento.isoformat(),            "paid_at":None,            "payment_method":None,            "status":"PENDING",            "created_at":datetime.utcnow().isoformat(),            "metadata":{                "origin":"099_BILLING_ENGINE"            }        }        assinatura=self._sha(payload)        self.conn.execute("""        INSERT INTO commercial_billings(            billing_uuid,            contract_uuid,            invoice_number,            amount,            currency,            issue_date,            due_date,            paid_at,            payment_method,            status,            created_at,            metadata,            hash        )        VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)        """,(            payload["billing_uuid"],            payload["contract_uuid"],            payload["invoice_number"],            payload["amount"],            payload["currency"],            payload["issue_date"],            payload["due_date"],            payload["paid_at"],            payload["payment_method"],            payload["status"],            payload["created_at"],            json.dumps(payload["metadata"],ensure_ascii=False),            assinatura        ))        self.conn.commit()        payload["hash"]=assinatura        return payload# ==============================================================================# TESTE# ==============================================================================if __name__=="__main__":    conn=sqlite3.connect(DB)    conn.row_factory=sqlite3.Row    contrato=conn.execute("""        SELECT contract_uuid        FROM commercial_contracts        LIMIT 1    """).fetchone()    if contrato is None:        raise RuntimeError("Nenhum contrato encontrado.")    engine=BillingEngine()    resultado=engine.create_billing(        contrato["contract_uuid"]    )    print("="*80)    print("BILLING ENGINE")    print("="*80)    for k,v in resultado.items():        print(f"{k:20}: {v}")    print("="*80)